SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- ==============================================================================
-- SECCION 0: CREACION IDEMPOTENTE DE ESQUEMA Y TABLAS EN 'sc_certificaciones'
-- ==============================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS sc_certificaciones;

CREATE TABLE IF NOT EXISTS sc_certificaciones.tb_concepto_historico (
    cohi_id       bigserial PRIMARY KEY,
    cohi_tipo     varchar,
    cohi_cod      varchar,
    cohi_nom      varchar,
    cohi_estado   varchar,
    usu_info      jsonb,
    fecha_created timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sc_certificaciones.tb_persona_historica (
    pers_id        bigserial PRIMARY KEY,
    pers_nombre    text,
    pers_apelpat   text,
    pers_apelmat   text,
    pers_fechnac   date,
    pers_ingreso   date,
    pers_cargo     text,
    pers_condicion varchar,
    pers_afp       date,
    pers_nom_afp   varchar,
    pers_c_essal   varchar,
    pers_dni       varchar(8),
    pers_codigo    varchar,
    pers_estado    varchar(1) DEFAULT 'A',
    usu_info       jsonb,
    fecha_created  timestamp with time zone DEFAULT now()
);

COMMENT ON COLUMN sc_certificaciones.tb_persona_historica.pers_afp IS 'Fecha de Afiliacion AFP (Columna 6 Hoja 1 / Alias export: Fecha_AFP)';
COMMENT ON COLUMN sc_certificaciones.tb_persona_historica.pers_nom_afp IS 'Nombre de la AFP (Columna 9 Hoja 1 / Alias export: pers_nom_afp)';
COMMENT ON COLUMN sc_certificaciones.tb_persona_historica.pers_c_essal IS 'Codigo Autogenerado EsSalud (Columna 8 Hoja 1 / Alias export: C_ESSAL)';

CREATE TABLE IF NOT EXISTS sc_certificaciones.tb_concepto_historico_persona (
    pers_cohi_id  bigserial PRIMARY KEY,
    periodo       integer,
    mes           integer,
    pers_id       integer REFERENCES sc_certificaciones.tb_persona_historica (pers_id),
    cohi_id       integer REFERENCES sc_certificaciones.tb_concepto_historico (cohi_id),
    monto         double precision,
    estado        varchar DEFAULT 'A',
    usu_info      jsonb,
    fecha_created timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sc_certificaciones.tb_evento_historico (
    evhi_id       bigserial PRIMARY KEY,
    evhi_nom      text,
    evhi_tipo     integer,
    evhi_estado   varchar,
    usu_info      jsonb,
    fecha_created timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sc_certificaciones.tb_evento_historico_persona (
    pers_evhi_id  bigserial PRIMARY KEY,
    periodo       integer,
    mes           integer,
    pers_id       integer REFERENCES sc_certificaciones.tb_persona_historica (pers_id),
    evhi_id       integer REFERENCES sc_certificaciones.tb_evento_historico (evhi_id),
    monto         varchar,
    estado        varchar DEFAULT 'A',
    usu_info      jsonb,
    fecha_created timestamp with time zone DEFAULT now()
);

COMMIT;

