) AS v(periodo, mes, pers_codigo, pers_dni, evhi_id, monto, estado)
JOIN sc_certificaciones.tb_persona_historica p
  ON (p.pers_codigo = v.pers_codigo OR (p.pers_codigo IS NULL AND v.pers_dni IS NOT NULL AND p.pers_dni = v.pers_dni))
WHERE NOT EXISTS (
    SELECT 1 FROM sc_certificaciones.tb_evento_historico_persona ehp
    WHERE ehp.periodo = v.periodo
      AND ehp.mes = v.mes
      AND ehp.pers_id = p.pers_id
      AND ehp.evhi_id = v.evhi_id
);
