    SELECT 1 FROM sc_certificaciones.tb_concepto_historico_persona chp
    WHERE chp.periodo = v.periodo
      AND chp.mes = v.mes
      AND chp.pers_id = p.pers_id
      AND chp.cohi_id = v.cohi_id
);
COMMIT;

