    (2015, 3, 'O6877', '16498555', 40, 0.00, 'A'),
    (2015, 3, 'O6877', '16498555', 8, 0.00, 'A')
) AS v(periodo, mes, pers_codigo, pers_dni, cohi_id, monto, estado)
JOIN sc_certificaciones.tb_persona_historica p
  ON (p.pers_codigo = v.pers_codigo OR (p.pers_codigo IS NULL AND v.pers_dni IS NOT NULL AND p.pers_dni = v.pers_dni))
WHERE NOT EXISTS (
    SELECT 1 FROM sc_certificaciones.tb_concepto_historico_persona chp
    WHERE chp.periodo = v.periodo
      AND chp.mes = v.mes
      AND chp.pers_id = p.pers_id
      AND chp.cohi_id = v.cohi_id
);
COMMIT;

